const d = new Date();
const ts = d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
const rand = Array.from({length: 8}, () => Math.floor(Math.random() * 16).toString(16)).join("");
const runKey = `LINEAR-GITHUB-RECON:${ts}:ORG:${rand}:v1`;
const lockScript = "C:\\Users\\lcvle\\.codex\\skills\\reconciliacao-linear-github\\scripts\\reconciliation-lock.ps1";
const r = await tools.exec_command({
  cmd: `& '${lockScript.replace(/'/g, "''")}' -Action acquire -RunKey '${runKey}' -TtlMinutes 1440`,
  shell: "pwsh",
  workdir: "C:\\Users\\lcvle\\lcv-workspace\\github-operations",
  yield_time_ms: 10000,
  max_output_tokens: 5000
});
if (r.exit_code !== 0) {
  text(JSON.stringify({ acquired: false, exit_code: r.exit_code, output: r.output.slice(0, 2000) }));
  exit();
}
const parsed = JSON.parse(r.output.trim());
const token = parsed.token || (parsed.lock && parsed.lock.token);
if (!token) {
  text(JSON.stringify({ acquired: false, exit_code: r.exit_code, reason: "token_missing", keys: Object.keys(parsed) }));
  exit();
}
store("audit_run_key", runKey);
store("audit_lock_token", token);
store("audit_started_at", d.toISOString());
text(JSON.stringify({
  acquired: true,
  run_key: runKey,
  locked: parsed.locked,
  busy: parsed.busy,
